0022Value\u0022: \u0022done\u0022,\n          \u0022VisitCap\u0022: 23,\n          \u0022Target\u0022: \u0022gated-merge\u0022\n        }\n      ],\n      \u0022Fields\u0022: [],\n      \u0022Sources\u0022: []\n    },\n    {\n      \u0022Name\u0022: \u0022worktree\u0022,\n      \u0022Agent\u0022: null,\n      \u0022AnswerSchema\u0022: null,\n      \u0022SystemStep\u0022: \u0022software/worktree\u0022,\n      \u0022Arguments\u0022: {},\n      \u0022Transitions\u0022: [\n        {\n          \u0022Field\u0022: \u0022verdict\u0022,\n          \u0022Value\u0022: \u0022done\u0022,\n          \u0022VisitCap\u0022: 3,\n          \u0022Target\u0022: \u0022rebase\u0022\n        }\n      ],\n      \u0022Fields\u0022: [],\n      \u0022Sources\u0022: []\n    },\n    {\n      \u0022Name\u0022: \u0022rebase\u0022,\n      \u0022Agent\u0022: null,\n      \u0022AnswerSchema\u0022: null,\n      \u0022SystemStep\u0022: \u0022software/rebase\u0022,\n      \u0022Arguments\u0022: {},\n      \u0022Transitions\u0022: [\n        {\n          \u0022Field\u0022: \u0022verdict\u0022,\n          \u0022Value\u0022: \u0022done\u0022,\n          \u0022VisitCap\u0022: 3,\n          \u0022Target\u0022: \u0022wait-for-checks\u0022\n        }\n      ],\n      \u0022Fields\u0022: [],\n      \u0022Sources\u0022: []\n    }\n  ]\n}","contentHash":"3ea9bf7b75a6e9f4","draftedBy":"coanda-import","draftedAt":"2026-11-05T08:23:42.524218+00:00","module":"software","moduleVersion":"0.1.0"}',NULL,'definition_drafted','2026-11-05T08:23:42.532Z','_node','Coanda.Core.Definitions.Events.DefinitionDrafted, Coanda.Core',0);
